R=Path(__file__).resolve().parents[1];OUT=R/'docs/Lezhandr_R04_modeling_report.pdf'
for name,fn in [('DV','DejaVuSans.ttf'),('DVB','DejaVuSans-Bold.ttf'),('DVM','DejaVuSansMono.ttf')]:pdfmetrics.registerFont(TTFont(name,'/usr/share/fonts/truetype/dejavu/'+fn))
pdfmetrics.registerFontFamily('DV',normal='DV',bold='DVB',italic='DV',boldItalic='DVB')
W,H=landscape(A3);M=42;INK=HexColor('#172B36');ACC=HexColor('#2F6273');MUT=HexColor('#596B73');BG=HexColor('#F7F6F2');LINE=HexColor('#D4DDDF');WARN=HexColor('#8B4E20')
c=canvas.Canvas(str(OUT),pagesize=(W,H));c.setTitle('Спим с хаски — Лежандр R04: пассивный откидной кожух и опыт драпировки');c.setAuthor('Проект Лежандр');c.setSubject('Реальные STEP-модели, результаты расчёта и скриншоты; коммерческий тканевый CAD не запускался')
page=0;flow=[]
def para(txt,x,top,width,size=12.2,leading=None,col=INK,bold=False):
    style=ParagraphStyle('p',fontName='DVB' if bold else 'DV',fontSize=size,leading=leading or size*1.42,textColor=col,spaceAfter=0)
    p=Paragraph(txt,style);_,hh=p.wrap(width,H);p.drawOn(c,x,H-top-hh);flow.append({'page':page,'top':top,'bottom':top+hh,'text':txt[:60]});return hh

def start(title,sub=''):
    global page
    if page:c.showPage()
    page+=1;c.setFillColor(BG);c.rect(0,0,W,H,fill=1,stroke=0)
    para('СПИМ С ХАСКИ  /  ЛЕЖАНДР  /  R04',M,22,760,10,col=ACC,bold=True)
    para(title,M,51,W-2*M,26,bold=True)
    if sub:para(sub,M,93,W-2*M,11.5,col=MUT)
    c.setStrokeColor(LINE);c.line(M,H-126,W-M,H-126);c.line(M,39,W-M,39)
    para('01.10.2026  •  Исследовательская ревизия, не выпуск в производство',M,H-27,900,8.5,col=MUT)
    c.setFont('DVB',10);c.setFillColor(ACC);c.drawRightString(W-M,19,f'{page:02d} / 12')

def image(rel,x,top,w,h):
    p=R/rel;im=Image.open(p);iw,ih=im.size;s=min(w/iw,h/ih);ww,hh=iw*s,ih*s
    c.drawImage(ImageReader(im),x+(w-ww)/2,H-top-hh-(h-hh)/2,width=ww,height=hh,mask='auto')

def tag(txt,x,top,w,col=ACC):
    c.setFillColor(col);c.roundRect(x,H-top-35,w,35,5,fill=1,stroke=0);para(txt,x+12,top+8,w-24,11,col=white,bold=True)

def table(rows,x,top,widths,size=11.5):
    sty=ParagraphStyle('t',fontName='DV',fontSize=size,leading=size*1.35,textColor=INK)
    data=[[Paragraph(str(v),sty) for v in row] for row in rows]
    t=Table(data,colWidths=widths,hAlign='LEFT');t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),HexColor('#DEE9EC')),('VALIGN',(0,0),(-1,-1),'TOP'),('LEFTPADDING',(0,0),(-1,-1),10),('RIGHTPADDING',(0,0),(-1,-1),10),('TOPPADDING',(0,0),(-1,-1),8),('BOTTOMPADDING',(0,0),(-1,-1),8),('LINEBELOW',(0,0),(-1,-1),.4,LINE)]));tw,th=t.wrap(sum(widths),H);t.drawOn(c,x,H-top-th);return th

def box(txt,x,top,w,h,col=HexColor('#E9EFF0')):
    c.setFillColor(col);c.roundRect(x,H-top-h,w,h,6,fill=1,stroke=0);para(txt,x+14,top+12,w-28,11.5)

hm=json.loads((R/'simulation/hood_metrics.json').read_text());fm=json.loads((R/'simulation/foot_quilt_metrics.json').read_text());sm=json.loads((R/'simulation/sleep_quilt_metrics.json').read_text());cl=json.loads((R/'tests/hood_clearances.json').read_text());ver=json.loads((R/'tests/verification.json').read_text());env=json.loads((R/'tests/environment.json').read_text());parts=json.loads((R/'patterns/patterns_R04.json').read_text());pp=next(p for p in parts if p['id']=='HC_OUTER');extent=np.ptp(pp['vertices_2d_mm'],axis=0);oldsm=json.loads((R/'simulation/rejected_trials/sleep_quilt_metrics.json').read_text())

